head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickListComiteDelibCaseSeq = "";

// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.setCode();
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60003.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60003.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60003.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60003.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        if (row === 0) return;
        if (colid === 'FILE1') {
            if (dts_List.getCellData(row, "FILE1") === '') {
                await $c.win.alert('첨부파일이 없습니다');
            } else {
                location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF60003.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + dts_List.getCellData(row, "LIST_COMITE_DELIB_CASE_SEQ") + "&attach_seq=1&gubun=28";
            }
        } else if (colid === 'FILE2') {
            if (dts_List.getCellData(row, "FILE2") === '') {
                await $c.win.alert('첨부파일이 없습니다');
            } else {
                location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF60003.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + dts_List.getCellData(row, "LIST_COMITE_DELIB_CASE_SEQ") + "&attach_seq=2&gubun=28";
            }
        } else {
            await scwin.openDetail(row);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60003.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60003.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60003.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_new_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_new_onclick = async function() {
    try {
        await scwin.openDetail(-999);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60003.btn_new_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60003.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let V_RSLT = " AND COMITE_INVSTG_RSLT_CD IN ( ";
    let atLeastChecked = false;
    if (chk_COMITE_RSLT1.checked) {
        V_RSLT += " '1' ";
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT2.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '2' ";
        } else {
            V_RSLT += " '2' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT3.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '3' ";
        } else {
            V_RSLT += " '3' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT4.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '4' ";
        } else {
            V_RSLT += " '4' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT5.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '5' ";
        } else {
            V_RSLT += " '5' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT6.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '6' ";
        } else {
            V_RSLT += " '6' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT7.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '7' ";
        } else {
            V_RSLT += " '7' ";
        }
        atLeastChecked = true;
    }
    if (atLeastChecked) {
        V_RSLT += " ) ";
    } else {
        V_RSLT = "";
    }
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
};

/**
 * @method
 * @name setListComiteDelibCaseSeq
 * @description set List Comite Delib Case Seq 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setListComiteDelibCaseSeq = function(obj) {
    scwin.clickListComiteDelibCaseSeq = dts_List.getCellData(Number(obj), "LIST_COMITE_DELIB_CASE_SEQ");
};

/**
 * @method
 * @name getListComiteDelibCaseSeq
 * @description get List Comite Delib Case Seq 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListComiteDelibCaseSeq = function() {
    return scwin.clickListComiteDelibCaseSeq;
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF60003.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "리스트", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    if (row > 0) {
        // 그리드에서 선택시
        scwin.setListComiteDelibCaseSeq(row);
    } else {
        // 신규버튼 선택시
        scwin.clickListComiteDelibCaseSeq = ""; // 초기화

    }

    // alert('[secugrpId]'+secugrpId);
    const options = {
        id: "ULDSTF60004",
        title: "상장위원회정보관리",
        type: "browserPopup",
        width: "900px",
        height: "600px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstmgt/ULDSTF60004.gfm", options);
};
